head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > getEventTarget]<br/>이벤트 핸들러 내에서 this 를 전달하면 호출한 컴포넌트의 pluginName 과 id 정보를 포함한 객체를 반환합니다.",
    "validation" : [
        "this(필수) 파라미터로 이벤트 핸들러 내의 this 객체를 설정할 수 있어야 합니다.",
        "반환 객체의 pluginName 속성으로 컴포넌트의 플러그인 이름을 확인할 수 있어야 합니다.",
        "반환 객체의 id 속성으로 컴포넌트의 원래 ID 를 확인할 수 있어야 합니다.",
        "반환 객체의 realId 속성으로 렌더링 과정에서 할당된 실제 내부 ID 를 확인할 수 있어야 합니다.",
        "전달된 값이 undefined, null, 빈 문자열인 경우 빈 객체를 반환해야 합니다.",
    ]
}



// comp 생성
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    $c.gcm.createLabel('label="target1(input) 값 변경 또는 target2(button) 클릭 시 getEventTarget 결과 출력"', '', 'label1');

    let ns = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    let strInput = '<w2:input ' + ns + ' ev:onchange="scwin.target1_onchange" style="width:200px;"></w2:input>';
    await $p.dynamicCreate('target1', 'input', strInput, grp_comp);

    let strBtn = '<w2:button ' + ns + ' ev:onclick="scwin.target2_onclick" label="target2 (button)" class="tc_btn_basic" style=""></w2:button>';
    await $p.dynamicCreate('target2', 'button', strBtn, grp_comp);
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 동적 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.target1_onchange = function () {
    let info = WebSquare.util.getEventTarget(this);
    let result = [];
    result.push("pluginName : " + info.pluginName);
    result.push("id : " + info.id);
    result.push("realId : " + info.realId);
    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}



scwin.target2_onclick = function () {
    let info = WebSquare.util.getEventTarget(this);
    let result = [];
    result.push("pluginName : " + info.pluginName);
    result.push("id : " + info.id);
    result.push("realId : " + info.realId);
    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}



scwin.btn_getEventTarget_empty_onclick = function () {
    let info = WebSquare.util.getEventTarget(null);
    let keys = Object.keys(info);
    wf_body_bottom.getObj("scwin").setReturnValue("getEventTarget(null) : 빈 객체 (keys: " + keys.length + ")");
}
